result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/src/school.js", "content": "import * as THREE from 'three';

/**
 * Deterministic PRNG (mulberry32). Returns a function producing
 * floats in [0, 1) from a 32-bit seed.
 */
function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const DEFAULT_MAX_SPEED = 2;
const SEPARATION_RADIUS = 0.5;

/**
 * Creates a fish school: flat Float32Array state plus one InstancedMesh
 * of cone-shaped fish. Pure logic + scene graph; no renderer required.
 */
export function createSchool({ count = 40, seed = 1, bounds } = {}) {
  const min = new Float32Array(bounds?.min ?? [-5, -5, -5]);
  const max = new Float32Array(bounds?.max ?? [5, 5, 5]);

  const rand = mulberry32(seed);

  const positions = new Float32Array(count * 3);
  const velocities = new Float32Array(count * 3);

  for (let i = 0; i < count; i++) {
    for (let axis = 0; axis < 3; axis++) {
      positions[i * 3 + axis] =
        min[axis] + rand() * (max[axis] - min[axis]);
      // Random initial heading with speed in [0.25, maxSpeed].
      const dir = rand() * 2 - 1;
      const speed = 0.25 + rand() * (DEFAULT_MAX_SPEED - 0.25);
      velocities[i * 3 + axis] = dir * speed;
    }
  }

  const geometry = new THREE.ConeGeometry(0.12, 0.45, 6);
  const material = new THREE.MeshStandardMaterial({ color: 0x66aaff });
  const mesh = new THREE.InstancedMesh(geometry, material, count);
  mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
  mesh.frustumCulled = false;

  // Write the initial instance matrices so the mesh is valid immediately.
  writeInstanceMatrices(mesh, positions, velocities, count);

  const school = {
    count,
    positions,
    velocities,
    bounds: { min, max },
    maxSpeed: DEFAULT_MAX_SPEED,
    separationRadius: SEPARATION_RADIUS,
    mesh,
  };

  return school;
}

const _centroid = new THREE.Vector3();
const _toCentroid = new THREE.Vector3();
const _desired = new THREE.Vector3();
const _steer = new THREE.Vector3();
const _sep = new THREE.Vector3();
const _diff = new THREE.Vector3();
const _vel = new THREE.Vector3();
const _pos = new THREE.Vector3();
const _quat = new THREE.Quaternion();
const _scale = new THREE.Vector3(1, 1, 1);
const _up = new THREE.Vector3(0, 1, 0); // cone points along +Y by default

/**
 * Advances the simulation by dt seconds:
 *  - soft steering toward the school centroid,
 *  - separation push for neighbours closer than separationRadius,
 *  - velocity clamped to maxSpeed,
 *  - position integration and reflection at the axis-aligned bounds,
 *  - instance matrices re-oriented along each fish's velocity.
 */
export function stepSchool(school, dt) {
  const { count, positions, velocities, bounds, maxSpeed } = school;
  const sepR = school.separationRadius;

  // Centroid of all fish.
  _centroid.set(0, 0, 0);
  for (let i = 0; i < count; i++) {
    _centroid.x += positions[i * 3];
    _centroid.y += positions[i * 3 + 1];
    _centroid.z += positions[i * 3 + 2];
  }
  if (count > 0) _centroid.divideScalar(count);

  const steerGain = 1.2; // soft steering strength (per second)
  const sepStrength = 6; // separation push strength

  for (let i = 0; i < count; i++) {
    const ix = i * 3;
    _pos.set(positions[ix], positions[ix + 1], positions[ix + 2]);
    _vel.set(velocities[ix], velocities[ix + 1], velocities[ix + 2]);

    // --- Soft steering toward the centroid -------------------------------
    _toCentroid.subVectors(_centroid, _pos);
    if (_toCentroid.lengthSq() > 1e-12) {
      _toCentroid.normalize();
      // Desired velocity: full speed toward the centroid...
      _desired.copy(_toCentroid).multiplyScalar(maxSpeed);
      // ...but steer softly: blend current velocity toward it.
      _steer.subVectors(_desired, _vel).multiplyScalar(steerGain);
    } else {
      _steer.set(0, 0, 0);
    }

    // --- Separation push --------------------------------------------------
    _sep.set(0, 0, 0);
    for (let j = 0; j < count; j++) {
      if (j === i) continue;
      const jx = j * 3;
      _diff.set(
        positions[ix] - positions[jx],
        positions[ix + 1] - positions[jx + 1],
        positions[ix + 2] - positions[jx + 2]
      );
      const d2 = _diff.lengthSq();
      if (d2 > 1e-12 && d2 < sepR * sepR) {
        // Push away, stronger when closer (inverse-square falloff).
        _diff.divideScalar(d2);
        _sep.add(_diff);
      }
    }
    _sep.multiplyScalar(sepStrength);

    // --- Integrate ---------------------------------------------------------
    _vel.addScaledVector(_steer, dt);
    _vel.addScaledVector(_sep, dt);

    // Clamp to maxSpeed.
    const speed = _vel.length();
    if (speed > maxSpeed) {
      _vel.multiplyScalar(maxSpeed / speed);
    }

    _pos.addScaledVector(_vel, dt);

    // --- Reflect at axis-aligned bounds ------------------------------------
    for (let axis = 0; axis < 3; axis++) {
      const comp = axis === 0 ? 'x' : axis === 1 ? 'y' : 'z';
      let p = _pos[comp];
      let v = _vel[comp];
      if (p < bounds.min[axis]) {
        p = 2 * bounds.min[axis] - p; // mirror back inside
        v = Math.abs(v); // flip outward component
        if (p > bounds.max[axis]) p = bounds.min[axis]; // degenerate-span safety
      } else if (p > bounds.max[axis]) {
        p = 2 * bounds.max[axis] - p;
        v = -Math.abs(v);
        if (p < bounds.min[axis]) p = bounds.max[axis];
      }
      _pos[comp] = p;
      _vel[comp] = v;
    }

    positions[ix] = _pos.x;
    positions[ix + 1] = _pos.y;
    positions[ix + 2] = _pos.z;
    velocities[ix] = _vel.x;
    velocities[ix + 1] = _vel.y;
    velocities[ix + 2] = _vel.z;
  }

  writeInstanceMatrices(school.mesh, positions, velocities, count);
}

/**
 * Composes one matrix per fish: translation at its position,
 * rotation aligning the cone's +Y axis with its velocity.
 */
function writeInstanceMatrices(mesh, positions, velocities, count) {
  const m = new THREE.Matrix4();
  for (let i = 0; i < count; i++) {
    const ix = i * 3;
    _pos.set(positions[ix], positions[ix + 1], positions[ix + 2]);
    _vel.set(velocities[ix], velocities[ix + 1], velocities[ix + 2]);
    if (_vel.lengthSq() > 1e-12) {
      _vel.normalize();
      _quat.setFromUnitVectors(_up, _vel);
    } else {
      _quat.identity(); // stationary fish keep pointing up
    }
    m.compose(_pos, _quat, _scale);
    mesh.setMatrixAt(i, m);
  }
  mesh.instanceMatrix.needsUpdate = true;
}
