result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test/school.test.js", "content": "import { describe, it, expect } from 'vitest';
import { createSchool, stepSchool } from '../src/school.js';

const COUNT = 40;
const SEED = 42;
const BOUNDS = { min: [-5, -3, -4], max: [5, 3, 4] };
const STEPS = 600;
const DT = 1 / 60;
const MAX_SPEED = 2;

function simulate() {
  const school = createSchool({ count: COUNT, seed: SEED, bounds: BOUNDS });
  for (let s = 0; s < STEPS; s++) {
    stepSchool(school, DT);
  }
  return school;
}

/** Average pairwise distance between all distinct fish. */
function averagePairwiseDistance(positions) {
  let sum = 0;
  let pairs = 0;
  for (let i = 0; i < positions.length / 3; i++) {
    for (let j = i + 1; j < positions.length / 3; j++) {
      const dx = positions[i * 3] - positions[j * 3];
      const dy = positions[i * 3 + 1] - positions[j * 3 + 1];
      const dz = positions[i * 3 + 2] - positions[j * 3 + 2];
      sum += Math.sqrt(dx * dx + dy * dy + dz * dz);
      pairs++;
    }
  }
  return sum / pairs;
}

describe('fish school', () => {
  it('keeps every fish inside the bounds over 600 steps', () => {
    const school = createSchool({ count: COUNT, seed: SEED, bounds: BOUNDS });
    for (let s = 0; s < STEPS; s++) {
      stepSchool(school, DT);
      for (let i = 0; i < COUNT; i++) {
        for (let axis = 0; axis < 3; axis++) {
          const p = school.positions[i * 3 + axis];
          expect(p).toBeGreaterThanOrEqual(BOUNDS.min[axis]);
          expect(p).toBeLessThanOrEqual(BOUNDS.max[axis]);
        }
      }
    }
  });

  it('produces no NaN in positions or velocities', () => {
    const school = simulate();
    for (const v of school.positions) expect(v).not.toBeNaN();
    for (const v of school.velocities) expect(v).not.toBeNaN();
  });

  it('never exceeds maxSpeed (within 1e-9)', () => {
    const school = createSchool({ count: COUNT, seed: SEED, bounds: BOUNDS });
    for (let s = 0; s <= STEPS; s++) {
      if (s > 0) stepSchool(school, DT);
      for (let i = 0; i < COUNT; i++) {
        const vx = school.velocities[i * 3];
        const vy = school.velocities[i * 3 + 1];
        const vz = school.velocities[i * 3 + 2];
        const speed = Math.sqrt(vx * vx + vy * vy + vz * vz);
        expect(speed).toBeLessThanOrEqual(MAX_SPEED + 1e-9);
      }
    }
  });

  it('cohesion: average pairwise distance shrinks after 600 steps', () => {
    const initial = createSchool({ count: COUNT, seed: SEED, bounds: BOUNDS });
    const d0 = averagePairwiseDistance(initial.positions);

    const final = simulate();
    const d600 = averagePairwiseDistance(final.positions);

    expect(d0).toBeGreaterThan(0);
    expect(d600).toBeLessThan(d0);
  });

  it('same seed reproduces identical trajectories', () => {
    const a = createSchool({ count: COUNT, seed: SEED, bounds: BOUNDS });
    const b = createSchool({ count: COUNT, seed: SEED, bounds: BOUNDS });
    for (let s = 0; s < STEPS; s++) {
      stepSchool(a, DT);
      stepSchool(b, DT);
    }
    expect([...a.positions]).toEqual([...b.positions]);
    expect([...a.velocities]).toEqual([...b.velocities]);

    // A different seed must differ.
    const c = createSchool({ count: COUNT, seed: SEED + 1, bounds: BOUNDS });
    for (let s = 0; s < STEPS; s++) stepSchool(c, DT);
    expect([...a.positions]).not.toEqual([...c.positions]);
  });
});
"})
